81	export const LiveSizeSelectionCard = (args: ZimmProductCardProps) => {
82	  // Lazy initializer: seeds from args.selectedSizeChipValue once on mount only, never re-syncs on rerender.
83	  const [selectedSizeChipValue, setSelectedSizeChipValue] = useState<string | undefined>(() =>
84	    args.variation === 'plp' || args.variation === 'wishlist' ? args.selectedSizeChipValue : undefined
85	  );
86	  const isSizeChipVariation = args.variation === 'plp' || args.variation === 'wishlist';
87	  const onSizeChipSelectFromArgs = isSizeChipVariation ? args.onSizeChipSelect : undefined;
88	  const handleSizeChipSelect = (value: string) => {
89	    setSelectedSizeChipValue(value);
90	    onSizeChipSelectFromArgs?.(value);
91	  };
92	  const propsWithLiveSelection: ZimmProductCardProps = isSizeChipVariation
93	    ? { ...args, selectedSizeChipValue, onSizeChipSelect: handleSizeChipSelect }
94	    : args;
95	  return createElement(ZimmProductCard, propsWithLiveSelection);
